"""Derive prompt-facing views of the current Mantle conversation state.

Pure functions: tracker + skill catalog + agent spec in, frozen plain-data
views out.  The views feed :mod:`rasa.mantle.prompts.templates`; they hold no
live tracker references, which keeps them trivially unit-testable.

Skills expose prompt instructions by flattening :class:`ProseBlock` segments
from ``body`` in document order. Ordered-block frames hide surrounding skill
prose so only the active step's guidance is shown.
"""

from __future__ import annotations

from enum import Enum
from typing import Collection, List, Mapping, Optional, Tuple

import structlog
from pydantic import BaseModel, ConfigDict

from rasa.dialogue_understanding.stack.frames.flow_stack_frame import (
    FlowStackFrameType,
    UserFlowStackFrame,
)
from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    MantleStackFrameType,
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.mantle.config.agent_spec import AgentSpec
from rasa.mantle.default_skills import (
    DEFAULT_UNSUPPORTED_REQUEST_HANDLER,
    DEFAULT_UNSUPPORTED_REQUEST_HANDLER_FLOW_ID,
)
from rasa.mantle.memory.field import MemoryEntry
from rasa.mantle.prompts.memory_lines import (
    format_memory_prompt_lines,
    partition_prompt_memory_entries,
)
from rasa.mantle.prompts.memory_prose import substitute_memory_prose_references
from rasa.mantle.skills.catalog import (
    ResolvedActivationTarget,
    SkillCatalog,
    is_ordered_block_target_id,
    is_prose_target_id,
    prose_segments_from_body,
    skill_has_prose,
)
from rasa.mantle.skills.prose_scoping import render_visible_instructions
from rasa.mantle.skills.skill import Skill
from rasa.mantle.skills.stack_frame_helpers import (
    SYNTHETIC_PROSE_STEP_ID,
    catalog_step_id,
    target_id_for_frame,
)
from rasa.mantle.skills.steps import AutonomousStep, CollectStep, Step
from rasa.mantle.state.pending_tool_confirmation import PendingToolConfirmation
from rasa.shared.core.trackers import DialogueStateTracker

structlogger = structlog.get_logger()

# ---------------------------------------------------------------------------
# Views (frozen data consumed by the templates)
# ---------------------------------------------------------------------------


class CollectTaskView(BaseModel):
    """The field the active collect step is gathering.

    Values are always recorded with ``set_fields`` (optional
    ``run_after_setting_<entry>`` memory validation tools run afterwards).
    """

    model_config = ConfigDict(frozen=True)

    field_name: str


class SkippedCollectView(BaseModel):
    """A collect step skipped this user turn because the value was already set.

    Surfaced in the same-turn ``### Already collected (do not re-ask)``
    notice and reminder after tool results. ``display_value`` is prompt-safe
    (PII redacted the same way as Memory).
    """

    model_config = ConfigDict(frozen=True)

    field_name: str
    display_value: str


class ReferencedSkillKind(str, Enum):
    """Kind tag for a skill the active skill hands off to."""

    SKILL_REFERENCE = "delegated — parent resumes"


class RoutableSkillView(BaseModel):
    """One skill row presented to the LLM.

    ``skill_id`` is the id the LLM passes to ``activate`` for this row.
    Routing, topic change, referenced skills, and interrupted tasks all use
    a skill id.

    ``kind`` labels a skill the active skill hands off to
    (:attr:`ReferencedSkillKind.SKILL_REFERENCE`, from prose ``@skill`` or a
    ``call:`` / ``link:`` to another skill). Leave ``None`` for routing and
    topic-change rows.
    """

    model_config = ConfigDict(frozen=True)

    skill_id: str
    description: str
    requires: Tuple[str, ...] = ()
    kind: Optional[ReferencedSkillKind] = None


class ActiveSkillView(BaseModel):
    """Everything the active-skill prompt section renders."""

    model_config = ConfigDict(frozen=True)

    name: str
    description: str
    instructions: str
    step_instructions: str
    step_complete_when: str
    step_optional: bool
    collect_task: Optional[CollectTaskView]
    skipped_collects: Tuple[SkippedCollectView, ...] = ()
    memory_lines: Tuple[str, ...]
    show_correction_reminder: bool
    show_correction_reentry_notice: bool
    interrupted_skills: Tuple[RoutableSkillView, ...]
    inline_parent_skill_id: str = ""
    inline_parent_step_instructions: str = ""
    paused_ordered_block_ids: Tuple[str, ...] = ()
    pending_tool_confirmation: Optional[PendingToolConfirmation] = None


class RoutingCatalogView(BaseModel):
    """Everything the routing-catalogue prompt section renders."""

    model_config = ConfigDict(frozen=True)

    routable_skills: Tuple[RoutableSkillView, ...]
    before_end: Tuple[str, ...] = ()
    routing_no_active: str = ""


# ---------------------------------------------------------------------------
# Public derivations
# ---------------------------------------------------------------------------


def active_target_id(tracker: Optional[DialogueStateTracker]) -> Optional[str]:
    """Compiled flow id of the topmost skill-path frame, or ``None``."""
    frame = _active_live_frame(tracker)
    if frame is None:
        return None
    return target_id_for_frame(frame)


def paused_ordered_block_target_ids(
    tracker: Optional[DialogueStateTracker],
    catalog: SkillCatalog,
) -> Tuple[str, ...]:
    """Compiled ids of same-skill blocks parked under the active frame.

    These are the ids the active-skill prompt tells the model to pass to
    ``activate``. Empty when nothing is parked.
    """
    frame = _active_live_frame(tracker)
    if not isinstance(frame, (UserFlowStackFrame, OrderedBlockStackFrame)):
        return ()
    return _paused_inline_sub_flow_ids(tracker, catalog, frame)


def active_skill_view(
    tracker: Optional[DialogueStateTracker],
    catalog: SkillCatalog,
    memory: dict,
    memory_cleared_by_correction: bool = False,
    correct_tool_available: bool = False,
    memory_entries: Optional[Mapping[str, MemoryEntry]] = None,
    pending_tool_confirmation: Optional[PendingToolConfirmation] = None,
    skipped_collects: Tuple[SkippedCollectView, ...] = (),
) -> Optional[ActiveSkillView]:
    """Build the active-skill view from the stack-top frame, or None.

    Returns ``None`` when no user-flow frame is active (routing mode).

    *memory* is the schema-scoped value view for the active skill (built by
    ``SkillExecutor.current_memory_values``), not raw tracker slots — so
    instruction filtering only exposes entries the active skill may actually
    read (public/private/project and cross-skill scoping are honoured, matching
    dispatch-time gating).

    *memory_entries* is the parallel :class:`MemoryEntry` view used for the
    ``### Memory:`` listing (skill-scoped set values; PII shown as
    ``[set]`` without the raw value) and for ``@memory`` substitution in
    instruction prose. Project slots are listed under ``### Project Memory``
    instead. Defaults to empty when omitted.

    *memory_cleared_by_correction* is the turn-scoped signal from
    ``TrackerHandle`` that a correction rewind cleared stale downstream memory;
    when set, the view flags the re-walk notice for the template.

    *correct_tool_available* is ``True`` when this turn offers the ``correct``
    tool (i.e. at least one earlier value is correctable). The correction
    reminder is shown only then, so the LLM is never told to call a tool that
    is not in its schema for the turn.

    *pending_tool_confirmation* surfaces a paused ``requires_confirmation`` gate so
    the template can tell the LLM to interpret the user's reply via
    ``resolve_tool_confirmation``.

    When the top frame is a block flow (``{skill_id}__{block_id}``), skill-level
    prose ``instructions`` are omitted so only the current step's guidance is
    shown; surrounding hybrid prose stays hidden until the block completes and
    the prose activation target is active again.
    """
    frame = _active_live_frame(tracker)
    if frame is None:
        return None

    target_id = target_id_for_frame(frame)
    target = catalog.resolve_activation_target(target_id)
    # Resolve the owning skill by target id, falling back to the frame's skill
    # id when the target no longer resolves (e.g. a stale frame after a model
    # upgrade) so the active-skill section still renders.
    skill = catalog.owning_skill_for_target_id(target_id) or catalog.skills.get(
        frame.skill_id
    )
    if skill is None and target is None:
        structlogger.warning(
            "mantle.prompts.state.active_skill_view.unresolved_frame",
            target_id=target_id,
            skill_id=frame.skill_id,
        )
        return None

    active_step = target.step_by_id(catalog_step_id(frame)) if target else None
    # Only suppress skill prose when the compiled block still resolves.
    # A stale ``skill__block`` id that no longer exists must fall back to skill
    # instructions (same path as a prose / skill-id frame).
    in_ordered_block = (
        target is not None
        and skill is not None
        and is_ordered_block_target_id(skill.id, target_id)
    )

    inline_parent_skill_id, inline_parent_step_instructions = _inline_parent_context(
        tracker, catalog, frame, memory, memory_entries
    )
    paused_ordered_block_ids = (
        _paused_inline_sub_flow_ids(tracker, catalog, frame)
        if isinstance(frame, (UserFlowStackFrame, OrderedBlockStackFrame))
        else ()
    )

    _, skill_entries = partition_prompt_memory_entries(memory_entries or {})
    return ActiveSkillView(
        name=_skill_display_name(skill, target_id),
        description=(skill.description if skill else None) or "",
        instructions=_active_skill_instructions(
            skill,
            target,
            memory,
            in_ordered_block=in_ordered_block,
            memory_entries=memory_entries,
        ),
        step_instructions=_active_step_instructions(
            active_step,
            skill,
            target,
            in_ordered_block=in_ordered_block,
            memory_entries=memory_entries,
        ),
        step_complete_when=_active_step_complete_when(active_step),
        step_optional=_active_step_optional(active_step),
        collect_task=_collect_task_view(active_step),
        skipped_collects=skipped_collects,
        memory_lines=format_memory_prompt_lines(skill_entries),
        show_correction_reminder=correct_tool_available,
        show_correction_reentry_notice=memory_cleared_by_correction,
        pending_tool_confirmation=pending_tool_confirmation,
        interrupted_skills=_interrupted_skills(tracker, catalog),
        inline_parent_skill_id=inline_parent_skill_id,
        inline_parent_step_instructions=inline_parent_step_instructions,
        paused_ordered_block_ids=paused_ordered_block_ids,
    )


def should_render_scope_handling(
    catalog: SkillCatalog,
    active_target_id: Optional[str],
) -> bool:
    """Whether the dedicated scope-handling section should render this turn.

    The section is static guidance (see ``scope_handling.jinja2``), so this is a
    pure gate: suppressed when the scope handler is already active (the
    active-skill section carries runtime instructions instead), or when the
    decline skill is absent from the catalogue.
    """
    active_skill = (
        catalog.owning_skill_for_target_id(active_target_id)
        if active_target_id is not None
        else None
    )
    if (
        active_skill is not None
        and active_skill.id == DEFAULT_UNSUPPORTED_REQUEST_HANDLER
    ) or active_target_id in {
        DEFAULT_UNSUPPORTED_REQUEST_HANDLER,
        DEFAULT_UNSUPPORTED_REQUEST_HANDLER_FLOW_ID,
    }:
        return False
    return DEFAULT_UNSUPPORTED_REQUEST_HANDLER in catalog.skills


def routing_catalog_view(
    catalog: SkillCatalog,
    agent: AgentSpec,
    memory: dict,
    *,
    allowed_target_ids: Optional[Collection[str]] = None,
) -> RoutingCatalogView:
    """Build the routing catalogue shown when no skill is active.

    Candidates come from :meth:`SkillCatalog.routable_entries` — the same
    source as the ``activate`` enum, excluding ``hidden`` and ``disabled``
    skills — so the catalogue and the tool schema can never disagree. Each
    row is a skill id labeled with that skill's description.
    """
    routable: List[RoutableSkillView] = []
    for skill_id, target_ids in catalog.routable_entries(memory).items():
        skill = catalog.skills.get(skill_id)
        if skill is None:
            continue
        for target_id in target_ids:
            if allowed_target_ids is not None and target_id not in allowed_target_ids:
                continue
            routable.append(_target_entry(skill, target_id))

    return RoutingCatalogView(
        routable_skills=tuple(routable),
        before_end=agent.before_end,
        routing_no_active=agent.prompts.routing_no_active_skill,
    )


def other_targets(
    catalog: SkillCatalog,
    active_target_id: Optional[str],
    memory: dict,
    *,
    exclude_target_ids: Collection[str] = (),
    allowed_target_ids: Optional[Collection[str]] = None,
) -> Tuple[RoutableSkillView, ...]:
    """Skill ids for topic change, excluding the active skill and referenced ids.

    Omits the active skill and any ids in *exclude_target_ids* (typically the
    skill ids from :func:`referenced_targets`), so the lifecycle prompt does
    not present the same skill as both a referenced skill and a topic change.
    """
    active_skill = (
        catalog.owning_skill_for_target_id(active_target_id)
        if active_target_id
        else None
    )
    active_skill_id = active_skill.id if active_skill else None
    excluded = set(exclude_target_ids)
    entries: List[RoutableSkillView] = []
    for skill_id, target_ids in catalog.routable_entries(memory).items():
        if skill_id == active_skill_id:
            continue
        skill = catalog.skills.get(skill_id)
        if skill is None:
            continue
        for target_id in target_ids:
            if target_id in excluded:
                continue
            if allowed_target_ids is not None and target_id not in allowed_target_ids:
                continue
            entries.append(_target_entry(skill, target_id))
    return tuple(entries)


def referenced_targets(
    catalog: SkillCatalog,
    memory: dict,
    *,
    active_skill_id: Optional[str],
    allowed_target_ids: Optional[Collection[str]] = None,
) -> Tuple[RoutableSkillView, ...]:
    """Skill ids for skills the active skill hands off to.

    Used in the lifecycle prompt to list those skills (prose ``@skill`` or a
    ``call:`` / ``link:`` to another skill) separately from topic changes.
    Each entry is tagged ``kind=ReferencedSkillKind.SKILL_REFERENCE``. When
    *allowed_target_ids* is set, only those ids are listed so the prompt
    matches the ``activate`` enum. The row id is the callee skill id, which
    is what ``activate`` starts.
    """
    if not active_skill_id:
        return ()
    parent = catalog.skill_by_id(active_skill_id)
    if parent is None or not parent.referenced_skills:
        return ()

    routable = set(catalog.routable_skill_ids(memory))
    seen_target_ids: set[str] = set()
    entries: List[RoutableSkillView] = []
    for target in parent.referenced_skills:
        callee_skill_id = catalog.referenced_callee_skill_id(target, active_skill_id)
        if callee_skill_id is None:
            continue
        callee = catalog.skill_by_id(callee_skill_id)
        if callee is None:
            continue
        target_id = callee.id
        if target_id not in routable or target_id in seen_target_ids:
            continue
        if allowed_target_ids is not None and target_id not in allowed_target_ids:
            continue
        seen_target_ids.add(target_id)
        entries.append(
            _target_entry(callee, target_id, kind=ReferencedSkillKind.SKILL_REFERENCE)
        )
    return tuple(entries)


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _active_live_frame(
    tracker: Optional[DialogueStateTracker],
) -> Optional[UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame]:
    """Topmost skill, ordered-block, or user-flow frame, or ``None``."""
    if tracker is None:
        return None
    for frame in reversed(tracker.stack.frames):
        if (
            isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame))
            and frame.frame_type == MantleStackFrameType.PENDING
        ):
            continue
        if isinstance(
            frame, (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame)
        ):
            return frame
    return None


def _active_user_frame(
    tracker: Optional[DialogueStateTracker],
) -> Optional[UserFlowStackFrame]:
    """Topmost ``UserFlowStackFrame``, or ``None`` (mirrors TrackerHandle)."""
    if tracker is None:
        return None
    top = tracker.stack.top()
    return top if isinstance(top, UserFlowStackFrame) else None


def _skill_display_name(skill: Optional[Skill], target_id: str) -> str:
    if skill is not None and skill.name:
        return skill.name
    if skill is not None:
        return skill.id
    return target_id


def _target_entry(
    skill: Skill,
    skill_id: str,
    *,
    kind: Optional[ReferencedSkillKind] = None,
) -> RoutableSkillView:
    """One prompt row labeled with the skill description."""
    return RoutableSkillView(
        skill_id=skill_id,
        description=skill.description or "",
        requires=(),
        kind=kind,
    )


def _substitute_instruction_memory(
    text: str,
    *,
    observing_skill_id: Optional[str],
    memory_entries: Optional[Mapping[str, MemoryEntry]],
) -> str:
    """Replace ``@memory`` tokens in assembled instruction text, if any."""
    if not text or not observing_skill_id:
        return text
    return substitute_memory_prose_references(
        text,
        observing_skill_id=observing_skill_id,
        memory_entries=memory_entries or {},
    )


def _active_skill_instructions(
    skill: Optional[Skill],
    target: Optional[ResolvedActivationTarget],
    memory: dict,
    *,
    in_ordered_block: bool,
    memory_entries: Optional[Mapping[str, MemoryEntry]] = None,
) -> str:
    """Skill-level instructions for the prompt, filtered for the current turn.

    Block flows (``{skill_id}__{block_id}``) omit surrounding skill prose so
    the LLM sees current-step guidance only. Prose entries render filtered
    prose segments — including ``if:``-scoped paragraphs when their
    conditions match current memory. Visible text then receives ``@memory``
    substitution against *memory_entries*.
    """
    if in_ordered_block:
        return ""
    if skill is None:
        return ""
    if target is not None and not is_prose_target_id(skill.id, target.target_id):
        return ""
    return _substitute_instruction_memory(
        render_visible_instructions(prose_segments_from_body(skill), memory),
        observing_skill_id=skill.id,
        memory_entries=memory_entries,
    )


def _active_step_instructions(
    active_step: Optional[Step],
    skill: Optional[Skill],
    target: Optional[ResolvedActivationTarget],
    *,
    in_ordered_block: bool = False,
    memory_entries: Optional[Mapping[str, MemoryEntry]] = None,
) -> str:
    """Per-step instructions of the active autonomous step, if any.

    Surfaced for mid-block autonomous steps in a multi-step ordered block.
    For the prose entry, skill-level filtered segments already own the prompt,
    so step instructions are omitted.

    Inside an ordered block, skill-level prose is hidden, so any autonomous step
    instructions are always returned. Returned text receives ``@memory``
    substitution against *memory_entries*.
    """
    if not isinstance(active_step, AutonomousStep):
        return ""
    if in_ordered_block:
        text = active_step.instructions
    elif (
        skill is not None
        and target is not None
        and is_prose_target_id(skill.id, target.target_id)
    ):
        return ""
    else:
        text = active_step.instructions
    return _substitute_instruction_memory(
        text,
        observing_skill_id=skill.id if skill is not None else None,
        memory_entries=memory_entries,
    )


def _find_inline_main_frame(
    catalog: SkillCatalog,
    user_frames: List[UserFlowStackFrame],
    active_frame: UserFlowStackFrame,
) -> Optional[UserFlowStackFrame]:
    """Return the routable inline main frame when an internal sub-flow is on top.

    Only used while the active top is a ``REGULAR`` internal sub-flow — so main
    is never the top here. Walks from the frame just under the top down toward
    the bottom and returns the first same-family ``is_inline_main`` frame
    (main may sit under or between parked same-skill blocks). Skips digression
    ``INTERRUPT`` ancestors. Returns ``None`` if the top is not an internal
    sub-flow or no main is found.
    """
    if active_frame.frame_type != FlowStackFrameType.REGULAR:
        return None
    if not catalog.is_internal_target(active_frame.flow_id):
        return None
    for frame in reversed(user_frames[:-1]):
        if frame.frame_type == FlowStackFrameType.INTERRUPT:
            continue
        if not catalog.is_same_inline_family(frame.flow_id, active_frame.flow_id):
            continue
        if catalog.is_inline_main(frame.flow_id):
            return frame
    return None


def _inline_parent_context(
    tracker: Optional[DialogueStateTracker],
    catalog: SkillCatalog,
    active_frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
    memory: dict,
    memory_entries: Optional[Mapping[str, MemoryEntry]] = None,
) -> Tuple[str, str]:
    """Main-flow instructions as context while an inline sub-flow is active.

    Prefers the parked main's autonomous step text. When that is empty (e.g.
    prose-only main), falls back to skill-level segments filtered for *memory*
    — unlike :func:`_active_skill_instructions`, which suppresses skill prose
    while an ordered block is the active top. Both paths substitute ``@memory``
    against *memory_entries*.

    Hybrid prose → block keeps the skill frame ``regular`` under the block;
    parent context then comes from that skill frame, not a parked flow.
    """
    if tracker is None:
        return "", ""
    if isinstance(active_frame, OrderedBlockStackFrame):
        return _skill_parent_context_for_block(
            tracker, catalog, active_frame, memory, memory_entries
        )
    if not isinstance(active_frame, UserFlowStackFrame):
        return "", ""
    user_frames = [
        frame for frame in tracker.stack.frames if isinstance(frame, UserFlowStackFrame)
    ]
    main_flow = _find_inline_main_frame(catalog, user_frames, active_frame)
    if main_flow is None:
        return "", ""
    parent_target = catalog.resolve_activation_target(main_flow.flow_id)
    skill = catalog.owning_skill_for_target_id(main_flow.flow_id)
    if parent_target is None or skill is None:
        return "", ""
    parent_step = parent_target.step_by_id(main_flow.step_id)
    instructions = _active_step_instructions(
        parent_step, skill, parent_target, memory_entries=memory_entries
    )
    if not instructions:
        instructions = _substitute_instruction_memory(
            render_visible_instructions(prose_segments_from_body(skill), memory),
            observing_skill_id=skill.id,
            memory_entries=memory_entries,
        )
    return skill.id, instructions


def _find_parent_regular_skill_frame(
    tracker: DialogueStateTracker,
    skill_id: str,
) -> Optional[SkillStackFrame]:
    """Return the ``regular`` skill frame for *skill_id* below the stack top."""
    frames = tracker.stack.frames
    if len(frames) < 2:
        return None
    for frame in reversed(frames[:-1]):
        if (
            isinstance(frame, SkillStackFrame)
            and frame.skill_id == skill_id
            and frame.frame_type == MantleStackFrameType.REGULAR
        ):
            return frame
    return None


def _skill_prose_parent_instructions(
    catalog: SkillCatalog,
    skill_id: str,
    memory: dict,
    memory_entries: Optional[Mapping[str, MemoryEntry]],
) -> str:
    """Return prose parent instructions for *skill_id*, or empty if unavailable."""
    parent_target = catalog.resolve_activation_target(skill_id)
    skill = catalog.skill_by_id(skill_id)
    if parent_target is None or skill is None:
        return ""
    parent_step = parent_target.step_by_id(SYNTHETIC_PROSE_STEP_ID)
    if parent_step is None and parent_target.steps:
        parent_step = parent_target.steps[0]
    instructions = _active_step_instructions(
        parent_step, skill, parent_target, memory_entries=memory_entries
    )
    if not instructions:
        instructions = _substitute_instruction_memory(
            render_visible_instructions(prose_segments_from_body(skill), memory),
            observing_skill_id=skill.id,
            memory_entries=memory_entries,
        )
    return instructions


def _skill_parent_context_for_block(
    tracker: DialogueStateTracker,
    catalog: SkillCatalog,
    active_frame: OrderedBlockStackFrame,
    memory: dict,
    memory_entries: Optional[Mapping[str, MemoryEntry]],
) -> Tuple[str, str]:
    """Return prose parent context from the ``regular`` skill under *active_frame*.

    A blocks-only skill has no prose to return to. Naming that skill id
    would tell the model to ``activate`` it and leave the called block.
    """
    parent_skill = _find_parent_regular_skill_frame(tracker, active_frame.skill_id)
    if parent_skill is None:
        return "", ""
    skill = catalog.skill_by_id(parent_skill.skill_id)
    if skill is None or not skill_has_prose(skill):
        return "", ""
    instructions = _skill_prose_parent_instructions(
        catalog, parent_skill.skill_id, memory, memory_entries
    )
    return parent_skill.skill_id, instructions


def _paused_inline_block_flow_ids(
    tracker: DialogueStateTracker,
    catalog: SkillCatalog,
    active_frame: OrderedBlockStackFrame,
) -> Tuple[str, ...]:
    """Return parked same-skill inline ordered-block flow ids below *active_frame*.

    Includes every ``INLINE_REFERENCE`` internal block for the same skill, in
    bottom-to-top stack order. Empty when nothing is parked or the top is not
    an active main (``REGULAR`` / ``CALL``).
    """
    block_frames = [
        block_frame
        for block_frame in tracker.stack.frames
        if isinstance(block_frame, OrderedBlockStackFrame)
        and block_frame.skill_id == active_frame.skill_id
    ]
    if len(block_frames) < 2 or block_frames[-1].frame_id != active_frame.frame_id:
        return ()
    if active_frame.frame_type not in (
        MantleStackFrameType.REGULAR,
        MantleStackFrameType.CALL,
    ):
        return ()
    paused_block_flow_ids: List[str] = []
    for block_frame in block_frames[:-1]:
        if block_frame.frame_type != MantleStackFrameType.INLINE_REFERENCE:
            continue
        flow_id = target_id_for_frame(block_frame)
        if not catalog.is_internal_target(flow_id):
            continue
        paused_block_flow_ids.append(flow_id)
    return tuple(paused_block_flow_ids)


def _paused_inline_sub_flow_ids(
    tracker: Optional[DialogueStateTracker],
    catalog: SkillCatalog,
    active_frame: UserFlowStackFrame | OrderedBlockStackFrame,
) -> Tuple[str, ...]:
    """Return parked same-skill inline sub-flow ids below the active top.

    Includes every ``INLINE_REFERENCE`` internal in the same family as the
    active flow, in bottom-to-top stack order. The top may be ``REGULAR`` or
    ``CALL`` (hybrid main entered via an outer ``call:``). Excludes the
    current top and non-internal frames (e.g. a parked main). Empty when
    nothing is parked or the top is not an active main (e.g. ``INTERRUPT``).
    """
    if tracker is None:
        return ()
    if isinstance(active_frame, OrderedBlockStackFrame):
        return _paused_inline_block_flow_ids(tracker, catalog, active_frame)

    user_frames = [
        frame for frame in tracker.stack.frames if isinstance(frame, UserFlowStackFrame)
    ]
    if len(user_frames) < 2:
        return ()
    top = user_frames[-1]
    if top.flow_id != active_frame.flow_id:
        return ()
    # Active main may be REGULAR or CALL (hybrid entered via outer call:);
    # both can have parked INLINE_REFERENCE subs underneath.
    if top.frame_type not in (
        FlowStackFrameType.REGULAR,
        FlowStackFrameType.CALL,
    ):
        return ()
    paused: List[str] = []
    for user_frame in user_frames[:-1]:
        if user_frame.frame_type != FlowStackFrameType.INLINE_REFERENCE:
            continue
        if not catalog.is_internal_target(user_frame.flow_id):
            continue
        if not catalog.is_same_inline_family(top.flow_id, user_frame.flow_id):
            continue
        paused.append(user_frame.flow_id)
    return tuple(paused)


def _active_step_complete_when(active_step: Optional[Step]) -> str:
    """Expression that advances the active autonomous step, if any."""
    if not isinstance(active_step, AutonomousStep) or not active_step.complete_when:
        return ""
    return str(active_step.complete_when)


def _active_step_optional(active_step: Optional[Step]) -> bool:
    """Whether the active autonomous step may be skipped without answering."""
    return isinstance(active_step, AutonomousStep) and active_step.optional is True


def _collect_task_view(active_step: Optional[Step]) -> Optional[CollectTaskView]:
    """Collect field when the active step is a CollectStep."""
    if not isinstance(active_step, CollectStep):
        return None
    return CollectTaskView(field_name=active_step.collect)


def _interrupted_skills(
    tracker: Optional[DialogueStateTracker],
    catalog: SkillCatalog,
) -> Tuple[RoutableSkillView, ...]:
    """Paused user tasks below the active frame, oldest first.

    The LLM resumes one by calling ``activate`` with its skill id.
    """
    if tracker is None:
        return ()
    frames = tracker.stack.frames
    if len(frames) < 2:
        return ()
    entries: List[RoutableSkillView] = []
    seen: set[str] = set()
    for frame in frames[:-1]:
        interrupted_id = _interrupted_target_id(frame)
        if interrupted_id is None:
            continue
        skill = (
            catalog.skill_by_id(frame.skill_id)
            if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame))
            else catalog.owning_skill_for_target_id(interrupted_id)
        )
        if skill is None or skill.id in seen:
            continue
        seen.add(skill.id)
        entries.append(_target_entry(skill, skill.id))
    return tuple(entries)


def _interrupted_target_id(
    frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame | object,
) -> Optional[str]:
    """Return the skill id for an interrupted frame, or ``None``."""
    if (
        isinstance(frame, UserFlowStackFrame)
        and frame.frame_type == FlowStackFrameType.INTERRUPT
    ):
        return frame.flow_id
    if (
        isinstance(frame, SkillStackFrame)
        and frame.frame_type == MantleStackFrameType.INTERRUPT
    ):
        return frame.skill_id
    if (
        isinstance(frame, OrderedBlockStackFrame)
        and frame.frame_type == MantleStackFrameType.INTERRUPT
    ):
        return frame.skill_id
    return None
